const fs=require('node:fs'),path=require('node:path');
const {JSDOM,VirtualConsole}=require('jsdom');
let w,time;
function mount(){const source=fs.readFileSync(path.join(__dirname,'../index.html'),'utf8');w=new JSDOM(source,{url:'http://localhost/',runScripts:'outside-only',virtualConsole:new VirtualConsole()}).window;time=1000;w.Date.now=()=>time;w.HTMLElement.prototype.checkVisibility=function(){return !this.hidden};w.HTMLDialogElement.prototype.showModal=function(){this.open=true};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'))};w.eval(source.match(/<script>([\s\S]*?)<\/script>/)[1]);click('example');click('start-candidate');return w.dianliangState.events[0]}
function click(action){const el=w.document.querySelector(`[data-action="${action}"]`);if(!el)throw Error('Missing '+action);el.click()}
function type(el,value){el.value=value;el.dispatchEvent(new w.Event('input',{bubbles:true}))}
function another(name){click('another');const f=w.document.querySelector('#another-form');f.elements.namedItem('name').value=name;f.dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));return w.dianliangState.events[0]}
afterEach(()=>w?.close());
it('keeps late note and step events attached to their original visible context',()=>{const first=mount();type(w.document.querySelector('#single-note'),'第一件事的草稿');const form=w.document.querySelector('#step-add');form.elements.namedItem('step').value='第一件事的步骤';form.dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));const oldDraft=w.document.querySelector('#single-note'),oldRepeat=w.document.querySelector('#repeat-note'),oldCheck=w.document.querySelector('[data-change^="step-check:"]'),oldSave=w.document.querySelector('#save-note');time=2000;const second=another('喝水');type(w.document.querySelector('#single-note'),'第二件事的草稿');const before=JSON.stringify(w.dianliangState);type(oldDraft,'迟到的输入');type(oldRepeat,'迟到的重复说明');oldCheck.checked=true;oldCheck.dispatchEvent(new w.Event('change',{bubbles:true}));oldSave.click();form.elements.namedItem('step').value='迟到的新步骤';form.dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));expect(JSON.stringify(w.dianliangState)).toBe(before);expect(first.draft).toBe('第一件事的草稿');expect(second.draft).toBe('第二件事的草稿');click('save-note');expect(second.notes.map(n=>n.text)).toEqual(['第二件事的草稿']);expect(second.draft).toBe('');expect(w.document.querySelector('[data-od-id="saved-notes"]').open).toBe(false);expect(first.notes).toEqual([])});
it('accumulates only active segments across many switches and ends paused events independently',()=>{const first=mount();time=2000;const second=another('喝水');time=3000;const third=another('打游戏');const sequence=[first,second,third,second,first,third,first,second];for(const e of sequence){time+=1000;click('resume:'+e.id);const state=w.dianliangState;expect(state.activeId).toBe(e.id);expect(state.events.flatMap(x=>x.segments).filter(p=>p.end===null)).toHaveLength(1)}time+=1000;click('finish:'+first.id);expect(w.dianliangState.activeId).toBe(second.id);expect(w.document.querySelector(`[data-event-id="${first.id}"]`)).toBeNull();click('dialog-close');time+=1000;click('finish:'+second.id);expect(w.dianliangState.activeId).toBeNull();expect(third.endedAt).toBeNull();expect(third.segments.every(p=>p.end!==null)).toBe(true);click('dialog-close');const total=w.dianliangState.events.flatMap(e=>e.segments).reduce((sum,p)=>sum+p.end-p.start,0);expect(total).toBe(time-1000);expect(first.endedAt).not.toBeNull();expect(second.endedAt).not.toBeNull()});
